    /**
     * Method to retrieve the Channel via ChannelFetchOneSummary
     * @param 	summary ChannelFetchOneSummary 
     * @return 	ChannelFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Channel getChannel( ChannelFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "ChannelFetchOneSummary arg cannot be null" );
    	
    	Channel entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Channel
        	// --------------------------------------
        	CompletableFuture<Channel> futureEntity = queryGateway.query(new FindChannelQuery( new LoadChannelFilter( summary.getChannelId() ) ), ResponseTypes.instanceOf(Channel.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Channel with id " + summary.getChannelId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


